-- Tables for every Django model, generated from the models (makemigrations reports no changes),
-- plus the django_migrations history so Django treats this database as fully migrated.
-- Applied to the Supabase project as migration "django_schema_and_rls" together with
-- 20261022000000_rls_public_read.sql, so no table was ever exposed without RLS.

CREATE TABLE "django_migrations" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" timestamp with time zone NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "user_id" integer NOT NULL, "content_type_id" integer NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_sitesettings" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "site_name" varchar(100) NOT NULL, "base_url" varchar(200) NOT NULL, "site_description" text NOT NULL, "primary_keywords" text NOT NULL, "secondary_keywords" text NOT NULL, "og_image" varchar(500) NOT NULL, "twitter_handle" varchar(50) NOT NULL, "google_analytics_id" varchar(50) NOT NULL, "google_search_console" text NOT NULL);
CREATE TABLE "formatter_blogcategory" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL, "slug" varchar(100) NOT NULL UNIQUE, "description" text NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_blogpost" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "title" text NOT NULL, "slug" varchar(250) NOT NULL UNIQUE, "category_id" bigint NOT NULL, "excerpt" text NOT NULL, "content" text NOT NULL, "tags" text NOT NULL, "meta_description" text NOT NULL, "meta_keywords" text NOT NULL, "published" boolean NOT NULL, "published_at" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "views" integer NOT NULL, "reading_time" integer NOT NULL, "author_name" varchar(100) NOT NULL, "author_profile_url" varchar(200) NOT NULL);
CREATE TABLE "formatter_visitorlog" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "ip_address" inet NOT NULL, "session_key" varchar(40) NULL, "country" varchar(100) NULL, "country_code" varchar(2) NULL, "city" varchar(100) NULL, "region" varchar(100) NULL, "latitude" numeric(9, 6) NULL, "longitude" numeric(9, 6) NULL, "user_agent" text NULL, "browser" varchar(100) NULL, "browser_version" varchar(50) NULL, "device_type" varchar(50) NULL, "os" varchar(100) NULL, "os_version" varchar(50) NULL, "referrer" varchar(500) NULL, "landing_page" varchar(500) NULL, "first_visit" timestamp with time zone NOT NULL, "last_visit" timestamp with time zone NOT NULL, "visit_count" integer NOT NULL, "total_page_views" integer NOT NULL, "is_bot" boolean NOT NULL, "is_mobile" boolean NOT NULL);
CREATE TABLE "formatter_pageview" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "visitor_id" bigint NULL, "url" varchar(500) NOT NULL, "page_title" varchar(200) NULL, "method" varchar(10) NOT NULL, "ip_address" inet NOT NULL, "user_agent" text NULL, "referrer" varchar(500) NULL, "timestamp" timestamp with time zone NOT NULL, "load_time" integer NULL, "session_key" varchar(40) NULL, "country_code" varchar(2) NULL, "device_type" varchar(50) NULL);
CREATE TABLE "formatter_contactmessage" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(200) NOT NULL, "email" varchar(254) NOT NULL, "subject" varchar(20) NOT NULL, "message" text NOT NULL, "created_at" timestamp with time zone NOT NULL, "ip_address" inet NULL, "user_agent" text NULL, "is_read" boolean NOT NULL, "is_replied" boolean NOT NULL, "replied_at" timestamp with time zone NULL, "notes" text NOT NULL);
CREATE TABLE "formatter_redirect" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "old_path" varchar(500) NOT NULL UNIQUE, "new_path" varchar(500) NOT NULL, "redirect_type" integer NOT NULL, "is_active" boolean NOT NULL, "hit_count" integer NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "notes" text NOT NULL);
CREATE TABLE "formatter_programminglanguage" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(50) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "icon" varchar(50) NOT NULL, "syntax_highlight" varchar(20) NOT NULL, "is_active" boolean NOT NULL, "order" integer NOT NULL);
CREATE TABLE "formatter_tutorialcategory" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL, "slug" varchar(100) NOT NULL UNIQUE, "description" text NOT NULL, "icon" varchar(50) NOT NULL, "order" integer NOT NULL);
CREATE TABLE "formatter_tutorial" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "title" varchar(200) NOT NULL, "slug" varchar(250) NOT NULL UNIQUE, "category_id" bigint NOT NULL, "description" text NOT NULL, "content" text NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" text NOT NULL, "meta_keywords" text NOT NULL, "order" integer NOT NULL, "is_published" boolean NOT NULL, "views" integer NOT NULL CHECK ("views" >= 0), "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_codeexample" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "tutorial_id" bigint NOT NULL, "language_id" bigint NOT NULL, "title" varchar(200) NOT NULL, "code" text NOT NULL, "output" text NOT NULL, "explanation" text NOT NULL, "order" integer NOT NULL);
CREATE TABLE "formatter_mcqquestion" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "tutorial_id" bigint NOT NULL, "question" text NOT NULL, "explanation" text NOT NULL, "order" integer NOT NULL);
CREATE TABLE "formatter_mcqoption" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "question_id" bigint NOT NULL, "option_text" varchar(500) NOT NULL, "is_correct" boolean NOT NULL, "order" integer NOT NULL);
CREATE TABLE "formatter_typingscore" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "username" varchar(50) NOT NULL, "session_key" varchar(100) NULL, "ip_address" inet NULL, "wpm" integer NOT NULL, "accuracy" numeric(5, 2) NOT NULL, "level" varchar(20) NOT NULL, "duration" integer NOT NULL, "total_characters" integer NOT NULL, "correct_characters" integer NOT NULL, "errors" integer NOT NULL, "created_at" timestamp with time zone NOT NULL, "is_verified" boolean NOT NULL);
CREATE TABLE "formatter_jobposting" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "title" varchar(200) NOT NULL, "slug" varchar(250) NOT NULL UNIQUE, "department" varchar(50) NOT NULL, "location" varchar(200) NOT NULL, "employment_type" varchar(20) NOT NULL, "description" text NOT NULL, "requirements" text NOT NULL, "responsibilities" text NOT NULL, "benefits" text NOT NULL, "salary_min" integer NULL CHECK ("salary_min" >= 0), "salary_max" integer NULL CHECK ("salary_max" >= 0), "salary_currency" varchar(10) NOT NULL, "show_salary" boolean NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" text NOT NULL, "meta_keywords" text NOT NULL, "is_active" boolean NOT NULL, "is_featured" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "apply_email" varchar(254) NOT NULL, "apply_url" varchar(200) NOT NULL);
CREATE TABLE "formatter_jobapplication" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "job_id" bigint NOT NULL, "full_name" varchar(200) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "cover_letter" text NOT NULL, "resume_url" varchar(200) NOT NULL, "portfolio_url" varchar(200) NOT NULL, "linkedin_url" varchar(200) NOT NULL, "years_of_experience" integer NOT NULL CHECK ("years_of_experience" >= 0), "current_company" varchar(200) NOT NULL, "current_role" varchar(200) NOT NULL, "status" varchar(20) NOT NULL, "ip_address" inet NULL, "user_agent" text NOT NULL, "applied_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "notes" text NOT NULL);
CREATE TABLE "formatter_mockendpoint" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "endpoint_id" varchar(36) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "path" varchar(200) NOT NULL, "method" varchar(10) NOT NULL, "status_code" integer NOT NULL, "response_body" text NOT NULL, "content_type" varchar(100) NOT NULL, "latency_ms" integer NOT NULL, "error_rate" integer NOT NULL, "record_count" integer NOT NULL, "ip_restriction_enabled" boolean NOT NULL, "allowed_ips" text NOT NULL, "custom_headers" text NOT NULL, "conditional_rules" text NOT NULL, "validation_schema" text NOT NULL, "auth_config" text NOT NULL, "is_public" boolean NOT NULL, "share_token" varchar(64) NULL, "creator_ip" inet NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "expires_at" timestamp with time zone NULL, "request_count" integer NOT NULL, "last_accessed" timestamp with time zone NULL);
CREATE TABLE "formatter_approveddomain" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "domain" varchar(255) NOT NULL UNIQUE, "is_indexable" boolean NOT NULL, "meta_title" varchar(255) NOT NULL, "meta_description" text NOT NULL, "notes" text NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_domainpagevisit" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "domain" varchar(255) NOT NULL UNIQUE, "visit_count" integer NOT NULL CHECK ("visit_count" >= 0), "unique_visitors" integer NOT NULL CHECK ("unique_visitors" >= 0), "last_cached_data" text NOT NULL, "cache_updated_at" timestamp with time zone NULL, "first_visit" timestamp with time zone NOT NULL, "last_visit" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_dummyjsonapilog" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "endpoint" varchar(20) NOT NULL, "ip_address" inet NOT NULL, "user_agent" text NULL, "request_count" integer NOT NULL CHECK ("request_count" >= 0), "first_request" timestamp with time zone NOT NULL, "last_request" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_networklookuplog" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "lookup_type" varchar(10) NOT NULL, "query" varchar(255) NOT NULL, "requester_ip" inet NOT NULL, "user_agent" text NULL, "response_data" jsonb NULL, "success" boolean NOT NULL, "error_message" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "formatter_toolusagelog" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "tool_name" varchar(100) NOT NULL, "action" varchar(100) NOT NULL, "ip_address" inet NULL, "user_agent" text NULL, "country" varchar(100) NULL, "city" varchar(100) NULL, "metadata" jsonb NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "apiutils_webhookendpoint" ("id" uuid NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL, "created_at" timestamp with time zone NOT NULL, "expires_at" timestamp with time zone NOT NULL, "session_key" varchar(64) NOT NULL);
CREATE TABLE "apiutils_capturedrequest" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "endpoint_id" uuid NOT NULL, "method" varchar(10) NOT NULL, "headers" jsonb NOT NULL, "body" text NOT NULL, "content_type" varchar(100) NOT NULL, "query_params" jsonb NOT NULL, "ip_address" inet NULL, "received_at" timestamp with time zone NOT NULL);
